const PD = 2;
const IS_4K = true;
const DRAW_INTERSECTION_POINTS = true;
const W = 1080;
const HW = Math.ceil(W/2);
const H = 1920;
const QH = Math.ceil(H/4);
const TH = Math.ceil(H/10);
const HH = Math.ceil(H/2);
const M = Math.ceil(W*0.09);
const CD = Math.ceil(W-M*2);
const CR = CD/2;
const RW = Math.ceil(CD*0.75);
const HRW = RW/2;
const HHRW = HRW/2;
const RM = (W-RW)/2;
const DBG = false;
const COL = [
	['#282828', '#F76951', '#F7AD72', '#FCF3DD', '#2D4F54', '#7e9692'],
	['#282828', '#2D4F54', '#FCF3DD'],
	//['#85aeff', '#1f34ab', '#0478ff', '#0f195a'],
	//['#ed225d', '#C91C4D', '#A1163E', '#78112E'],
	//['#b6dc9f', '#98c800', '#146f43'],
	//['#8ce4df', '#2d9e97', '#104b58'],
	//['#85aeff', '#1f34ab', '#0478ff', '#ed225d', '#b6dc9f', '#98c800', '#146f43', '#8ce4df', '#2d9e97', '#104b58'],
];
const MIN_RR = 2;
const MAX_RR = 3;
const MIN_RR_2 = 1;
const MAX_RR_2 = 2;
let PIX;
let RS = 0;
let leftIntersectionPoints, middleIntersectionPoints, rightIntersectionPoints;
let lipIx = 0, mipIx = 0, ripIx = 0;
let intersectionCircles;

function setup() {
	createCanvas(W, H);
	pixelDensity(PD);
	blendMode(DIFFERENCE);
	background('#282828');
	noStroke();

	leftIntersectionPoints   = [];
	middleIntersectionPoints = [];
	rightIntersectionPoints  = [];
	lipIx = 0;
	mipIx = 0;
	ripIx = 0;
	intersectionCircles = [];

	RS = round(random(0, 1e9));
	//RS = 999999999;
	randomSeed(RS);
	console.debug(`randomSeed: ${RS}`);

	p5grain.setup();

	if (DRAW_INTERSECTION_POINTS) {
		// calculate and draw intersection points
		const rectX = HW-HRW;
		const intersections1 = calculateIntersections(HW, HH, CR, rectX, HRW);
		const intersections2 = calculateIntersections(HW, HH, CR, rectX+HRW, HRW).slice(2);

		leftIntersectionPoints = [
			createVector(intersections1[0].x, 0),
			createVector(intersections1[0].x, height),
			createVector(intersections1[0].x, round(intersections1[0].y)),
			createVector(intersections1[1].x, round(intersections1[1].y)),
		];
		middleIntersectionPoints = [
			createVector(HW, 0),
			createVector(HW, height),
			createVector(intersections1[2].x, round(intersections1[2].y)),
			createVector(intersections1[3].x, round(intersections1[3].y)),
		];
		//middleIntersectionPoints.push(createVector(HW, HH));
		rightIntersectionPoints = [
			createVector(intersections2[0].x, 0),
			createVector(intersections2[0].x, height),
			createVector(intersections2[0].x, round(intersections2[0].y)),
			createVector(intersections2[1].x, round(intersections2[1].y)),
		];

		// draw intersection points (left + middle)
		let left_x, left_y_top, left_y_bottom, left_dist;
		let left_y_outside_top_dist, left_y_outside_bottom_dist;
		let middle_x, middle_y_top, middle_y_bottom, middle_dist;
		let middle_y_outside_top_dist, middle_y_outside_bottom_dist;
		//fill(COL[PIX][floor(random(0, COL[PIX].length))]);
		for (let i = 0; i < intersections1.length; i++) {
			let cd, cr;
			if (! IS_4K) {
				cd = floor(random(PD>1?16:64, PD>1?64:256));
				//circle(intersections1[i].x, intersections1[i].y, cd);
				intersectionCircles.push([intersections1[i].x, intersections1[i].y, cd]);
			} else {
				cd = floor(random(48, 196));
				//circle(intersections1[i].x, intersections1[i].y, cd);
				intersectionCircles.push([intersections1[i].x, intersections1[i].y, cd]);
			}
			cr = cd/2;
			const y_less = intersections1[i].y-cr;
			const y_more = intersections1[i].y+cr;
			if (i === 0) {
				left_y_outside_top_dist = y_less;
			} else if (i === 1) {
				left_y_outside_bottom_dist = height - y_more;
			} else if (i === 2) {
				middle_y_outside_top_dist = y_less;
			} else if (i === 3) {
				middle_y_outside_bottom_dist = height - y_more;
			}
			if (i === 0 || i === 1) {
				leftIntersectionPoints.push(createVector(intersections1[i].x, round(y_less)));
				leftIntersectionPoints.push(createVector(intersections1[i].x, round(y_more)));	
			} else if (i === 2 || i === 3) {
				middleIntersectionPoints.push(createVector(intersections1[i].x, round(y_less)));
				middleIntersectionPoints.push(createVector(intersections1[i].x, round(y_more)));	
			}
			if (i === 0 || i === 1) {
				if (left_x === undefined) {
					left_x = intersections1[i].x;	
				}
				if (i === 0) {
					left_y_top = y_more;
				} else if (i === 1) {
					left_y_bottom = y_less;
				}
				const circlesIntersectionPoints = calculateCirclesIntersections(
					HW, HH, CR, intersections1[i].x, intersections1[i].y, cr
				);
				for (let j = 0; j < circlesIntersectionPoints.length; j++) {
					if (
						(i === 0 && circlesIntersectionPoints[j].y <= intersections1[i].y) ||
						(i === 1 && circlesIntersectionPoints[j].y >= intersections1[i].y)
					) {
						leftIntersectionPoints.push(createVector(left_x, round(circlesIntersectionPoints[j].y)));
						// intersections1[2].x -> middle_x
						//middleIntersectionPoints.push(createVector(intersections1[2].x, round(circlesIntersectionPoints[j].y)));
					}
				}
			} else if (i === 2 || i === 3) {
				if (middle_x === undefined) {
					middle_x = intersections1[i].x;
				}
				if (i === 2) {
					middle_y_top = y_more;
				} else if (i === 3) {
					middle_y_bottom = y_less;
				}
			}
		}
		// left intersections
		left_y_dist = left_y_bottom - left_y_top;
		const left_y_dist_g = left_y_dist*0.382;
		leftIntersectionPoints.push(createVector(left_x, round(left_y_top+left_y_dist_g)));
		leftIntersectionPoints.push(createVector(left_x, round(left_y_top+left_y_dist*0.5)));
		leftIntersectionPoints.push(createVector(left_x, round(left_y_bottom-left_y_dist_g)));
		// left top outside
		leftIntersectionPoints.push(createVector(left_x, round(left_y_outside_top_dist*0.382)));
		leftIntersectionPoints.push(createVector(left_x, round(left_y_outside_top_dist*0.5)));
		leftIntersectionPoints.push(createVector(left_x, round(left_y_outside_top_dist*0.618)));
		// left bottom outside
		leftIntersectionPoints.push(createVector(left_x, round(height - left_y_outside_bottom_dist*0.382)));
		leftIntersectionPoints.push(createVector(left_x, round(height - left_y_outside_bottom_dist*0.5)));
		leftIntersectionPoints.push(createVector(left_x, round(height - left_y_outside_bottom_dist*0.618)));
		// middle intersections
		middle_y_dist = middle_y_bottom - middle_y_top;
		const middle_y_dist_g = middle_y_dist*0.382;
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_top+middle_y_dist_g)));
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_top+middle_y_dist*0.5)));
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_bottom-middle_y_dist_g)));
		// middle top outside
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_outside_top_dist*0.382)));
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_outside_top_dist*0.5)));
		middleIntersectionPoints.push(createVector(middle_x, round(middle_y_outside_top_dist*0.618)));
		// middle bottom outside
		middleIntersectionPoints.push(createVector(middle_x, round(height - middle_y_outside_bottom_dist*0.382)));
		middleIntersectionPoints.push(createVector(middle_x, round(height - middle_y_outside_bottom_dist*0.5)));
		middleIntersectionPoints.push(createVector(middle_x, round(height - middle_y_outside_bottom_dist*0.618)));

		// draw intersection points (right)
		let right_x, right_y_top, right_y_bottom, right_dist;
		let right_y_outside_top_dist, right_y_outside_bottom_dist;
		for (let i = 0; i < intersections2.length; i++) {
			let cd;
			if (! IS_4K) {
				cd = floor(random(PD>1?16:64, PD>1?64:256));
				//circle(intersections2[i].x, intersections2[i].y, cd);
				intersectionCircles.push([intersections2[i].x, intersections2[i].y, cd]);
			} else {
				cd = floor(random(48, 196));
				//circle(intersections2[i].x, intersections2[i].y, cd);
				intersectionCircles.push([intersections2[i].x, intersections2[i].y, cd]);
			}
			cr = cd/2;
			const y_less = intersections2[i].y-cr;
			const y_more = intersections2[i].y+cr;
			if (i === 0) {
				right_y_outside_top_dist = y_less;
			} else if (i === 1) {
				right_y_outside_bottom_dist = height - y_more;
			}
			//if (i === 0 || i === 1) {
				rightIntersectionPoints.push(createVector(intersections2[i].x, round(y_less)));
				rightIntersectionPoints.push(createVector(intersections2[i].x, round(y_more)));
			//}
			if (i === 0 || i === 1) {
				if (right_x === undefined) {
					right_x = intersections2[i].x;	
				}
				if (i === 0) {
					right_y_top = y_more;
				} else if (i === 1) {
					right_y_bottom = y_less;
				}
				const circlesIntersectionPoints = calculateCirclesIntersections(
					HW, HH, CR, intersections2[i].x, intersections2[i].y, cr
				);
				for (let j = 0; j < circlesIntersectionPoints.length; j++) {
					if (
						(i === 0 && circlesIntersectionPoints[j].y <= intersections2[i].y) ||
						(i === 1 && circlesIntersectionPoints[j].y >= intersections2[i].y)
					) {
						rightIntersectionPoints.push(createVector(right_x, round(circlesIntersectionPoints[j].y)));
						//middleIntersectionPoints.push(createVector(middle_x, round(circlesIntersectionPoints[j].y)));
					}
				}
			}
		}
		// right intersections
		right_y_dist = right_y_bottom - right_y_top;
		const right_y_dist_g = right_y_dist*0.382;
		rightIntersectionPoints.push(createVector(right_x, round(right_y_top+right_y_dist_g)));
		rightIntersectionPoints.push(createVector(right_x, round(right_y_top+right_y_dist*0.5)));
		rightIntersectionPoints.push(createVector(right_x, round(right_y_bottom-right_y_dist_g)));
		// right top outside
		rightIntersectionPoints.push(createVector(right_x, round(right_y_outside_top_dist*0.382)));
		rightIntersectionPoints.push(createVector(right_x, round(right_y_outside_top_dist*0.5)));
		rightIntersectionPoints.push(createVector(right_x, round(right_y_outside_top_dist*0.618)));
		// right bottom outside
		rightIntersectionPoints.push(createVector(right_x, round(height - right_y_outside_bottom_dist*0.382)));
		rightIntersectionPoints.push(createVector(right_x, round(height - right_y_outside_bottom_dist*0.5)));
		rightIntersectionPoints.push(createVector(right_x, round(height - right_y_outside_bottom_dist*0.618)));
