		fill('#f00');
		for (let i = 0; i < leftIntersectionPoints.length; i++) {
			circle(leftIntersectionPoints[i].x, leftIntersectionPoints[i].y, 10);
		}
		for (let i = 0; i < middleIntersectionPoints.length; i++) {
			circle(middleIntersectionPoints[i].x, middleIntersectionPoints[i].y, 10);
		}
		for (let i = 0; i < rightIntersectionPoints.length; i++) {
			circle(rightIntersectionPoints[i].x, rightIntersectionPoints[i].y, 10);
		}
	}

	for (let i = 0; i < 1000; i++) {
		const colIx = floor(random(0, COL[PIX].length));
		const col = color(COL[PIX][colIx]);
		col.setAlpha(3);
		fill(col);
		const cx = floor(random(0, width));
		const cy = floor(random(0, height));
		let cd = floor(random(10, PD>1?200:800));
		cd = ! IS_4K ? cd : 256;
		circle(cx, cy, cd);
	}
	fill('#ffffff08');
	for (let i = 0; i < 10000; i++) {
		const cx = floor(random(0, width));
		const cy = floor(random(0, height));
		const cd = floor(random(0, 4));
		circle(cx, cy, cd);
	}
	fill('#ffffff0f');
	for (let i = 0; i < 10000; i++) {
		const cx = floor(random(0, width));
		const cy = floor(random(0, height));
		const cd = floor(random(1, 2));
		circle(cx, cy, cd);
	}
	fill('#f00');
	for (let i = 0; i < floor(random(32, 64)); i++) {
		const px = floor(random(0, width));
		const py = floor(random(0, height));
		let ps = PD>1?1:2;
		ps = ! IS_4K ? ps : 1;
		rect(px, py, ps, ps);
	}
	let grainAmount = PD>1?16:19;
	grainAmount = ! IS_4K ? grainAmount : 19;
	p5grain.granulateSimple(grainAmount);
}

function leftRR(rx) {
	/*let nextY = 0;
	let _wG_1 = 0; while ((nextY <= height) && ++_wG_1 < 20000) {
		const rh = floor(random(QH, TH));
		const colIx = floor(random(0, COL[PIX].length));
		fill(COL[PIX][colIx]);
		rect(rx, nextY, HRW, rh);
		nextY += rh;
	}*/
	const last_lipIx = leftIntersectionPoints.length-1;
	const last_mipIx = middleIntersectionPoints.length-1;
	//const last_ripIx = rightIntersectionPoints.length-1;
	let is_lip_turn = true;
	let currY = 0;
	let _wG_2 = 0; while ((currY < height) && ++_wG_2 < 20000) {
		if (is_lip_turn) {
			const inc_mipIx = floor(random(MIN_RR, MAX_RR));
			if ((mipIx + inc_mipIx) <= last_mipIx) {
				mipIx += inc_mipIx;
			} else {
				mipIx = last_mipIx;
			}
			const rh = middleIntersectionPoints[mipIx].y - leftIntersectionPoints[lipIx].y;
			const colIx = floor(random(0, COL[PIX].length));
			fill(COL[PIX][colIx]);
			rect(rx, currY, HRW, rh);
			currY += rh;
			is_lip_turn = false;
		}
		else { // is_mip_turn
			const inc_lipIx = floor(random(MIN_RR, MAX_RR));
			if ((lipIx + inc_lipIx) <= last_lipIx) {
				lipIx += inc_lipIx;
			} else {
				lipIx = last_lipIx;
			}
			const rh = leftIntersectionPoints[lipIx].y - middleIntersectionPoints[mipIx].y;
			const colIx = floor(random(0, COL[PIX].length));
			fill(COL[PIX][colIx]);
			rect(rx, currY, HRW, rh);
			currY += rh;
			is_lip_turn = true;
		}
	}
}

function rightRR(rx) {
	const last_mipIx = middleIntersectionPoints.length-1;
	const last_ripIx = rightIntersectionPoints.length-1;
	let is_mip_turn = true;
	let currY = 0;
	let _wG_3 = 0; while ((currY < height) && ++_wG_3 < 20000) {
		if (is_mip_turn) {
			const inc_ripIx = floor(random(MIN_RR_2, MAX_RR_2));
			if ((ripIx + inc_ripIx) <= last_ripIx) {
				ripIx += inc_ripIx;
			} else {
				ripIx = last_ripIx;
			}
			const rh = rightIntersectionPoints[ripIx].y - middleIntersectionPoints[mipIx].y;
			const colIx = floor(random(0, COL[PIX].length));
			fill(COL[PIX][colIx]);
			rect(rx, currY, HRW, rh);
			currY += rh;
			is_mip_turn = false;
		}
		else { // is_rip_turn
			const inc_mipIx = floor(random(MIN_RR_2, MAX_RR_2));
			if ((mipIx + inc_mipIx) <= last_mipIx) {
				mipIx += inc_mipIx;
			} else {
				mipIx = last_mipIx;
			}
			const rh = middleIntersectionPoints[mipIx].y - leftIntersectionPoints[lipIx].y;
			const colIx = floor(random(0, COL[PIX].length));
			fill(COL[PIX][colIx]);
			rect(rx, currY, HRW, rh);
			currY += rh;
			is_mip_turn = true;
		}
	}
}

