function calculateIntersections(circleX, circleY, circleRadius, rectX, rectWidth) {
  const intersections = [];
  // left side intersection points
  const leftIntersectY1 = circleY - sqrt(circleRadius * circleRadius - (rectX - circleX) * (rectX - circleX));
  const leftIntersectY2 = circleY + sqrt(circleRadius * circleRadius - (rectX - circleX) * (rectX - circleX));
  intersections.push(createVector(rectX, leftIntersectY1));
  intersections.push(createVector(rectX, leftIntersectY2));
  // right side intersection points
  const rightIntersectY1 = circleY - sqrt(circleRadius * circleRadius - (rectX + rectWidth - circleX) * (rectX + rectWidth - circleX));
  const rightIntersectY2 = circleY + sqrt(circleRadius * circleRadius - (rectX + rectWidth - circleX) * (rectX + rectWidth - circleX));
  intersections.push(createVector(rectX + rectWidth, rightIntersectY1));
  intersections.push(createVector(rectX + rectWidth, rightIntersectY2));
  return intersections;
}

function calculateCirclesIntersections(x1, y1, r1, x2, y2, r2) {
  const points = [];
  // calculate the distance between the circle centers
  const d = dist(x1, y1, x2, y2);
  // check if the circles intersect
  if (d < r1 + r2 && d > abs(r1 - r2)) {
    // calculate the intersection points
    const a = (r1 * r1 - r2 * r2 + d * d) / (2 * d);
    const h = sqrt(r1 * r1 - a * a);
    // calculate the coordinates of the intersection points
    const x3 = x1 + (a * (x2 - x1)) / d;
    const y3 = y1 + (a * (y2 - y1)) / d;
    const intersectionPoint1 = createVector(
      x3 + (h * (y2 - y1)) / d,
      y3 - (h * (x2 - x1)) / d
    );
    const intersectionPoint2 = createVector(
      x3 - (h * (y2 - y1)) / d,
      y3 + (h * (x2 - x1)) / d
    );
    points.push(intersectionPoint1, intersectionPoint2);
  }
  return points;
}

